#include <stdlib.h>
int compute(void){int n=4;int *a=(int*)malloc(sizeof(int)*n);if(!a)return -1;for(int i=0;i<n;i++)a[i]=14+i;int s=0;for(int i=0;i<n;i++)s+=a[i];free(a);return s;}
int main(void){printf("%d\n", compute());return 0;}

