int compute(void){int a[3]={3,17,1};int *p=a;for(int i=0;i<3;i++){for(int j=0;j<2;j++){if(p[j]>p[j+1]){int t=p[j];p[j]=p[j+1];p[j+1]=t;}}}return p[0]+p[2];}
int main(void){printf("%d\n", compute());return 0;}

